class ColumnsOnlyProvider(MetaDataProvider):
    """a custom provider written before keys support, only with _get_table_columns"""

    def _get_table_columns(self, schema: str, table: str, **kwargs) -> list[str]:
        return {"db2.orders": ["order_id", "customer_id"]}.get(f"{schema}.{table}", [])


class CountingProvider(DummyMetaDataProvider):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.key_lookups: list[str] = []

    def get_table_keys(self, table: Table) -> TableKeys:
        self.key_lookups.append(str(table))
        return super().get_table_keys(table)


class FailingKeysProvider(DummyMetaDataProvider):
    def _get_primary_key(self, schema: str, table: str) -> list[str]:
        raise RuntimeError("boom")

    def _get_foreign_keys(self, schema: str, table: str) -> list[ForeignKey]:
        raise RuntimeError("boom")


def test_models_normalize_and_sort():
    fk_b = ForeignKey(["Customer_ID"], Table("DB2.Customers"), ["ID"])
    fk_a = ForeignKey(("a",), Table("db2.zzz"), ("x",))
    fk_a2 = ForeignKey(("a",), Table("db2.aaa"), ("x",))
    assert fk_b.columns == ("customer_id",)
    assert fk_b.referred_columns == ("id",)
    assert fk_b.referred_table == Table("db2.customers")
    assert ForeignKey(('"Quoted"',), Table("t"), ("x",)).columns == ("Quoted",)
    keys = TableKeys(primary_key=["Order_Id"], foreign_keys=(fk_b, fk_a, fk_a2))
    assert keys.primary_key == ("order_id",)
    assert keys.foreign_keys == (fk_a2, fk_a, fk_b)
    assert keys == TableKeys(("order_id",), (fk_a, fk_b, fk_a2))
    assert hash(keys) == hash(TableKeys(("order_id",), (fk_a, fk_b, fk_a2)))
    assert keys
    assert not TableKeys()
    assert TableKeys() == TableKeys((), ())


